 10  /** Keep the source report's policy context compact; full indexed graph evidence has its own command. */
 11  export function sourceArchitectureContext(rules: ArchitectureReport) {
 12    return {
 13      configured: rules.configured,
 14      boundaries: rules.boundaries,
 15      coverage: rules.coverage,
 16      policyCoverage: rules.policyCoverage,
 17      dependencyRoles: rules.dependencyRoles,
 18      cycles: rules.cycles.map((cycle) => ({
 19        boundaries: cycle.boundaries, origin: cycle.origin, fileCycleMembers: cycle.fileCycleMembers,
 20        violatesPolicy: cycle.violatesPolicy,
 21      })),
 22    };
 23  }
 24  
 25  export function sourceTestFile(file: string, config?: ArchitectureConfig): boolean {
 26    return (
 27      classifyFile(file) === 'test' ||
 28      /(^|\/)(fixtures|benchmarks)(\/|$)/.test(file) ||
 29      (config?.testPaths ?? []).some((pattern) => matchesPathGlob(pattern, file))
 30    );
 31  }
 32  
 33  export function importGraph(files: readonly string[], imports: readonly SourceImport[]): Map<string, Set<string>> {
 34    const graph = new Map(files.map((file) => [file, new Set<string>()]));
 35    for (const edge of imports)
 36      if (edge.resolution === 'internal' && edge.target && graph.has(edge.target)) graph.get(edge.file)?.add(edge.target);
 37    return graph;
 38  }
 39  
 40  export function productionImports(imports: readonly SourceImport[], config?: ArchitectureConfig): SourceImport[] {
 41    return imports.filter(
 42      (edge) => !sourceTestFile(edge.file, config) && (!edge.target || !sourceTestFile(edge.target, config)),
 43    );
 44  }
 45  
 46  export function eagerValueImports(imports: readonly SourceImport[]): SourceImport[] {
 47    return imports.filter((edge) => edge.kind === 'value' && (edge.syntax === 'import' || edge.syntax === 'reexport'));
 48  }
 49  
 50  export function dependencyCoverage(imports: readonly SourceImport[]) {
 51    const resolutions: Record<ImportResolution, number> = {
 52      internal: 0,
 53      external: 0,
 54      builtin: 0,
 55      excluded: 0,
 56      missing: 0,
 57      ambiguous: 0,
 58      dynamic: 0,
 59    };
 60    for (const edge of imports) resolutions[edge.resolution]++;
 61    return {
 62      resolutions,
 63      typeOnly: imports.filter((edge) => edge.kind === 'type').length,
 64      test: imports.filter((edge) => edge.role === 'test').length,
 65      deferredOrCommonJs: imports.filter((edge) => edge.syntax === 'dynamic-import' || edge.syntax === 'require').length,
 66      unresolved: imports.filter(
 67        (edge) => edge.resolution === 'missing' || edge.resolution === 'ambiguous' || edge.resolution === 'dynamic',
 68      ),
 69      excluded: imports.filter((edge) => edge.resolution === 'excluded'),
 70    };
 71  }
 72  
 73  export function dependencyCycleFindings(files: readonly string[], imports: readonly SourceImport[]): SourceFinding[] {
 74    const edges = eagerValueImports(imports);
 75    const graph = importGraph(files, edges);
 76    return stronglyConnectedComponents(graph)
 77      .components.filter((members) => members.length > 1 || graph.get(members[0]!)?.has(members[0]!))
 78      .map((members) => {
 79        const contained = new Set(members);
 80        const references = edges.filter(
 81          (edge) =>
 82            edge.resolution === 'internal' && contained.has(edge.file) && edge.target && contained.has(edge.target),
 83        );
 84        return {
 85          id: `dependency-cycle:${[...members].sort().join('|')}`,
 86          rule: 'dependency-cycle',
 87          evidence: 'derived',
 88          summary: `${members.length} production files form a circular component of static value imports.`,
 89          score: members.length,
 90          sites: references.map((edge) => ({ file: edge.file, line: edge.line })),
 91          details: references.map((edge) => `${edge.file}:${edge.line} → ${edge.target} (${edge.syntax}, ${edge.kind})`),
 92        };
 93      });
 94  }
