 96  export function sourceArchitecture(
 97    files: readonly string[],
 98    imports: readonly SourceImport[],
 99    config?: ArchitectureConfig,
100  ) {
101    const production = productionImports(imports, config);
102    const rules = analyzeArchitectureGraph(importGraph(files, production), files, config);
103    const owners = new Map(files.map((file) => [file, architectureBoundaryForFile(config, file)]));
104    const findings: SourceFinding[] = rules.forbiddenEdges.map((edge) => {
105      const references = production.filter(
106        (item) =>
107          item.resolution === 'internal' &&
108          item.target &&
109          owners.get(item.file) === edge.from &&
110          owners.get(item.target) === edge.to,
111      );
112      return {
113        id: `architecture:${edge.from}:${edge.to}`,
114        rule: 'architecture',
115        evidence: 'derived',
116        summary: `${edge.from} → ${edge.to}: ${edge.fileEdgeCount} production file dependencies violate the declared rule.`,
117        sites: references.flatMap((item) => [
118          { file: item.file, line: item.line },
119          { file: item.target!, line: 1 },
120        ]),
121        score: edge.fileEdgeCount,
122        details: references.map((item) => `${item.file}:${item.line} → ${item.target} (${item.kind}, ${item.syntax})`),
123      };
124    });
125    for (const cycle of rules.cycles.filter((item) => item.violatesPolicy)) {
126      const references = production.filter(
127        (edge) =>
128          edge.resolution === 'internal' &&
129          edge.target &&
130          cycle.boundaries.includes(owners.get(edge.file) ?? '') &&
131          cycle.boundaries.includes(owners.get(edge.target) ?? ''),
132      );
133      findings.push({
134        id: `architecture:group-cycle:${cycle.boundaries.join('|')}`,
135        rule: 'architecture',
136        evidence: 'derived',
137        score: cycle.boundaries.length,
138        summary: `Declared groups ${cycle.boundaries.join(', ')} violate requireAcyclic (${cycle.origin}).`,
139        sites: references.map((edge) => ({ file: edge.file, line: edge.line })),
140        details: [
141          rules.dependencyRoles!.cycleMeaning,
142          ...references.map((edge) => `${edge.file}:${edge.line} → ${edge.target} (${edge.kind}, ${edge.syntax})`),
143        ],
144      });
145    }
146    for (const limit of rules.boundaryLimits)
147      findings.push({
148        id: `architecture:limit:${limit.boundary}:${limit.kind}`,
149        rule: 'architecture',
150        evidence: 'derived',
151        score: limit.observed,
152        summary: `${limit.boundary}: ${limit.observed} ${limit.kind} exceeds the declared limit ${limit.limit}.`,
153        sites: files.filter((file) => owners.get(file) === limit.boundary).map((file) => ({ file, line: 1 })),
154        details: ['A configured bound is a project rule, not proof that a group has multiple responsibilities.'],
155      });
156    if (rules.policyCoverage.requiresCompleteCoverage) {
157      for (const file of rules.coverage.unmappedFiles)
158        findings.push({
159          id: `architecture:unmapped:${file}`,
160          rule: 'architecture',
161          evidence: 'derived',
162          score: 1,
163          summary: `${file} has no declared boundary and violates requireCompleteCoverage.`,
164          sites: [{ file, line: 1 }],
165          details: [],
166        });
167      for (const item of rules.coverage.ambiguousFiles)
168        findings.push({
169          id: `architecture:ambiguous:${item.file}`,
170          rule: 'architecture',
171          evidence: 'derived',
172          score: item.boundaries.length,
173          summary: `${item.file} matches multiple declared boundaries and violates requireCompleteCoverage.`,
174          sites: [{ file: item.file, line: 1 }],
175          details: item.boundaries,
176        });
177    }
178    return { rules, findings };
179  }
