181  export function unresolvedImportFindings(imports: readonly SourceImport[]): SourceFinding[] {
182    return imports
183      .filter((edge) => edge.resolution === 'missing' || edge.resolution === 'ambiguous')
184      .map((edge) => ({
185        id: `broken-dependency:${edge.file}:${edge.specifier}`,
186        rule: 'broken-dependency',
187        evidence: 'candidate',
188        summary: `${JSON.stringify(edge.specifier)} ${edge.resolution === 'ambiguous' ? 'has conflicting project resolutions' : 'does not resolve in the captured internal source'}.`,
189        sites: [{ file: edge.file, line: edge.line }],
190        score: 1,
191        details: [
192          `Configuration: ${edge.configs.join(', ') || 'default compiler resolution'}.`,
193          'Check the import, project configuration, generated files and custom loaders before treating this as a broken build.',
194        ],
195      }));
