198  export function relationshipChanges(before: readonly SourceImport[], after: readonly SourceImport[]): string[] {
199    const grouped = (imports: readonly SourceImport[]): Map<string, string> => {
200      const result = new Map<string, string[]>();
201      for (const edge of imports) {
202        const facts = result.get(edge.file) ?? [];
203        facts.push(
204          JSON.stringify([
205            edge.specifier,
206            edge.target,
207            edge.resolution,
208            edge.kind,
209            edge.role,
210            edge.syntax,
211            edge.alternatives,
212          ]),
213        );
214        result.set(edge.file, facts);
215      }
216      return new Map([...result].map(([file, facts]) => [file, facts.sort().join('\n')]));
217    };
218    const old = grouped(before),
219      next = grouped(after);
220    return [...new Set([...old.keys(), ...next.keys()])].filter((file) => old.get(file) !== next.get(file)).sort();
221  }
