 10  export interface SourceModuleSubject {
 11    id: string;
 12    basis: 'declared-boundary' | 'directory';
 13    files: string[];
 14    consumers: string[];
 15    dependencies: string[];
 16    findingIds: string[];
 17    primaryFindingIds: string[];
 18    highestPriority: SourceFinding['rule'];
 19    interpretation: string;
 20  }
