 22  /** Group findings for planning; directory membership is location evidence, not a discovered responsibility. */
 23  export function sourceModuleSubjects(
 24    files: readonly string[],
 25    imports: readonly SourceImport[],
 26    findings: readonly SourceFinding[],
 27    config?: ArchitectureConfig,
 28  ): SourceModuleSubject[] {
 29    const groups = new Map<string, SourceModuleSubject>();
 30    const owners = new Map<string, string>();
 31    for (const file of files) {
 32      const boundary = architectureBoundaryForFile(config, file);
 33      const id = boundary ? `boundary:${boundary}` : `directory:${path.posix.dirname(file)}`;
 34      owners.set(file, id);
 35      if (!groups.has(id))
 36        groups.set(id, {
 37          id,
 38          basis: boundary ? 'declared-boundary' : 'directory',
 39          files: [],
 40          consumers: [],
 41          dependencies: [],
 42          findingIds: [],
 43          primaryFindingIds: [],
 44          highestPriority: 'complexity',
 45          interpretation:
 46            'Grouping identifies declared membership or a shared directory. Review the observed contracts before changing ownership.',
 47        });
 48      groups.get(id)!.files.push(file);
 49    }
 50    const outgoing = new Map<string, Set<string>>(),
 51      incoming = new Map<string, Set<string>>();
 52    for (const edge of productionImports(imports, config)) {
 53      if (edge.resolution !== 'internal' || !edge.target) continue;
 54      const from = owners.get(edge.file),
 55        to = owners.get(edge.target);
 56      if (!from || !to || from === to) continue;
 57      const targets = outgoing.get(from) ?? new Set<string>();
 58      targets.add(edge.target);
 59      outgoing.set(from, targets);
 60      const sources = incoming.get(to) ?? new Set<string>();
 61      sources.add(edge.file);
 62      incoming.set(to, sources);
 63    }
 64    const sorted = [...findings].filter((finding) => finding.status !== 'resolved').sort(compareFindings);
 65    const rank = new Map(sorted.map((finding, index) => [finding.id, index]));
 66    for (const finding of sorted) {
 67      const primary = finding.sites.map((site) => owners.get(site.file)).find((id) => id !== undefined);
 68      if (primary) groups.get(primary)!.primaryFindingIds.push(finding.id);
 69      for (const id of new Set(
 70        finding.sites.map((site) => owners.get(site.file)).filter((id): id is string => Boolean(id)),
 71      )) {
 72        const group = groups.get(id)!;
 73        if (!group.findingIds.length) group.highestPriority = finding.rule;
 74        group.findingIds.push(finding.id);
 75      }
 76    }
 77    return [...groups.values()]
 78      .filter((group) => group.findingIds.length)
 79      .map((group) => ({
 80        ...group,
 81        files: group.files.sort(),
 82        consumers: [...(incoming.get(group.id) ?? [])].sort(),
 83        dependencies: [...(outgoing.get(group.id) ?? [])].sort(),
 84      }))
 85      .sort(
 86        (a, b) =>
 87          (rank.get(a.primaryFindingIds[0]!) ?? Infinity) - (rank.get(b.primaryFindingIds[0]!) ?? Infinity) ||
 88          a.id.localeCompare(b.id),
 89      );
 90  }
