 92  /** Independent implementations, dependencies and named consumer sets are leads for a responsibility review. */
 93  export function responsibilityFindings(facts: readonly MaintenanceBindingFacts[]): SourceFinding[] {
 94    const consumers = facts.flatMap((item) => item.consumers);
 95    const findings: SourceFinding[] = [];
 96    for (const fileFacts of facts) {
 97      if (fileFacts.functions.length < 4) continue;
 98      const file = fileFacts.functions[0]!.fn.file;
 99      const groups = independentFunctionGroups(fileFacts.functions)
100        .map((group) => {
101          const exports = new Set(group.flatMap((item) => item.exports));
102          return {
103            functions: group.filter((item) => item.exports.length && item.fn.tokenCount >= 60),
104            dependencies: [...new Set(group.flatMap((item) => item.dependencies))],
105            consumers: consumers.filter((item) => item.target === file && (exports.has(item.name) || item.name === '*')),
106          };
107        })
108        .filter((group) => group.functions.length >= 2 && group.dependencies.length && group.consumers.length);
109      const independent = groups.filter((group) =>
110        groups.every(
111          (other) =>
112            group === other ||
113            !other.consumers.some((consumer) => group.consumers.some((item) => item.file === consumer.file)),
114        ),
115      );
116      if (independent.length < 2) continue;
117      findings.push({
118        id: `responsibility:${file}`,
119        rule: 'responsibility',
120        evidence: 'candidate',
121        score: independent.length,
122        summary: `${file} contains ${independent.length} substantial exported function groups with separate observed dependencies and named consumers.`,
123        sites: independent.flatMap((group) =>
124          group.functions.map(({ fn }) => ({ file, line: fn.startLine, name: fn.name })),
125        ),
126        details: independent
127          .map(
128            (group, index) =>
129              `Group ${index + 1}: ${group.functions.map((item) => item.fn.name).join(', ')}; dependencies: ${group.dependencies.join(', ')}; named importers: ${group.consumers.map((item) => `${item.file}:${item.line} (${item.name})`).join(', ')}.`,
130          )
131          .concat([
132            'No shared same-file binding or imported module connects these groups in the covered top-level functions. Nested closures contribute their binding references to their containing function.',
133            'A shared public contract can justify keeping these groups together. Classes, indirect re-exports, dynamic consumers, external users and runtime resource identity are not established by this provider. Read those contracts before proposing a split.',
134          ]),
135      });
136    }
137    return findings;
138  }
139  
140  function independentFunctionGroups(functions: readonly MaintenanceFunctionBindings[]): MaintenanceFunctionBindings[][] {
141    const graph = new Map(functions.map((_, index) => [String(index), new Set<string>()]));
142    const owners = new Map<string, string>();
143    functions.forEach((fn, index) => {
144      const current = String(index);
145      for (const key of [
146        ...[fn.declaration, ...fn.bindings].map((offset) => `binding:${offset}`),
147        ...fn.dependencies.map((file) => `import:${file}`),
148      ]) {
149        const previous = owners.get(key);
150        if (previous !== undefined) {
151          graph.get(current)!.add(previous);
152          graph.get(previous)!.add(current);
153        } else owners.set(key, current);
154      }
155    });
156    return stronglyConnectedComponents(graph).components.map((members) =>
157      members.map((member) => functions[Number(member)]!),
158    );
159  }
