 62  export function sourceMaintenanceReport(projectRoot: string, opts: SourceReviewOptions = {}): SourceMaintenanceReport {
 63    const current = currentSourceSnapshot(projectRoot, opts);
 64    const coverageInput = loadReviewCoverage(projectRoot, opts.coverage);
 65    const analysis = analyzeSourceSnapshot(current, coverageInput, opts.architecture);
 66    const base = opts.base === undefined ? undefined : baseSourceSnapshot(projectRoot, opts.base, opts);
 67    const before = base ? analyzeSourceSnapshot(base, undefined, opts.architecture) : undefined;
 68    const changedFiles = base
 69      ? [...new Set([...base.files.keys(), ...current.files.keys()])]
 70          .filter((file) => base.files.get(file) !== current.files.get(file))
 71          .sort()
 72      : [];
 73    const configurationChanges = base
 74      ? [...new Set([...base.project.inputs.keys(), ...current.project.inputs.keys()])]
 75          .filter((file) => base.project.inputs.get(file) !== current.project.inputs.get(file))
 76          .sort()
 77      : [];
 78    const relationshipChangedFiles = before ? relationshipChanges(before.imports, analysis.imports) : [];
 79    const policyChanged =
 80      base &&
 81      JSON.stringify(opts.architecture ?? base.project.architecture) !==
 82        JSON.stringify(opts.architecture ?? current.project.architecture);
 83    const problems = [
 84      ...analysis.problems,
 85      ...(before?.problems.map((problem) => `base: ${problem}`) ?? []),
 86      ...assertSourceSnapshotCurrent(projectRoot, current, opts),
 87    ];
 88    const scope = opts.scope?.replaceAll('\\', '/').replace(/^\.\//, '').replace(/\/$/, '');
 89    const inScope = (file: string): boolean => !scope || scope === '.' || file === scope || file.startsWith(scope + '/');
 90    if (scope && ![...current.files.keys(), ...(base?.files.keys() ?? [])].some(inScope)) {
 91      problems.push(`Scope ${JSON.stringify(scope)} matches no analyzed source file; check the path and exclusions.`);
 92    }
 93    const sourceComparable = problems.length === 0;
 94    const changed = new Set([...changedFiles, ...relationshipChangedFiles]);
 95    if (policyChanged) for (const file of [...current.files.keys(), ...(base?.files.keys() ?? [])]) changed.add(file);
 96    problems.push(...current.project.problems, ...(base?.project.problems.map((problem) => `base: ${problem}`) ?? []));
 97    const functionChanges = before ? changedFunctions(before.functions, analysis.functions) : [];
 98    const relevantFunctions = (
 99      before ? functionChanges.flatMap((change) => (change.after ? [change.after] : [])) : analysis.functions
100    ).filter((fn) => inScope(fn.file));
101    const testCoverage = summarizeTestCoverage(relevantFunctions, Boolean(opts.coverage), coverageInput.problem);
102    if (testCoverage.requested && testCoverage.reasons.length)
103      problems.push(`Requested test coverage is incomplete: ${testCoverage.reasons.join('; ')}`);
104    const compared = before
105      ? compareSourceFindings(
106          before,
107          analysis,
108          changed,
109          sourceComparable,
110          !current.project.problems.length && !base?.project.problems.length,
111        )
112      : analysis.findings;
113    if (before) {
114      for (const finding of removedDependencyFindings(before, analysis, changed, sourceComparable)) {
115        const index = compared.findIndex((item) => item.id === finding.id);
116        if (index >= 0) compared[index] = finding;
117        else compared.push(finding);
118      }
119    }
120    const findings = compared
121      .filter((finding) => !scope || finding.sites.some((site) => inScope(site.file)))
122      .sort(compareFindings);
123    const modules = sourceModuleSubjects(
124      [...current.files.keys()],
125      analysis.imports,
126      findings,
127      opts.architecture ?? current.project.architecture,
128    );
129    const dependencies = dependencyCoverage(analysis.imports);
130    if (dependencies.resolutions.missing || dependencies.resolutions.ambiguous)
131      problems.push(
132        `${dependencies.resolutions.missing} internal imports unresolved; ${dependencies.resolutions.ambiguous} ambiguous. Inspect coverage.dependencies.unresolved or scoped findings.`,
133      );
134    return {
135      mode: base ? 'review' : 'health',
136      ...(base ? { base: base.revision } : {}),
137      current: current.fingerprint,
138      metricRules: 'typescript-function-local-v1',
139      changedFiles: changedFiles.filter(inScope),
140      configurationChanges,
141      relationshipChangedFiles: relationshipChangedFiles.filter(inScope),
142      architecture: sourceArchitectureContext(analysis.architecture),
143      functions: functionChanges
144        .filter((change) => inScope((change.after ?? change.before)!.file))
145        .map((change) =>
146          !sourceComparable ? { status: 'uncomparable', before: change.before, after: change.after } : change,
147        ),
148      findings,
149      modules,
150      affectedFiles: before
151        ? [
152            ...new Set([
153              ...relationshipChangedFiles.filter((file) => inScope(file) && !changedFiles.includes(file)),
154              ...affectedImporters(before.graph, new Set([...changedFiles, ...relationshipChangedFiles].filter(inScope))),
155              ...affectedImporters(
156                analysis.graph,
157                new Set([...changedFiles, ...relationshipChangedFiles].filter(inScope)),
158              ),
159            ]),
160          ].sort()
161        : [],
162      coverage: {
163        status: problems.length ? 'incomplete' : 'accounted',
164        analyzedFiles: current.files.size,
165        eligibleFiles: current.eligibleFiles,
166        excludedFiles: current.excludedFiles,
167        exclusions: current.exclusions,
168        dependencies,
169        analyzedFunctions: analysis.functions.length,
170        unresolvedImports: dependencies.resolutions.missing + dependencies.resolutions.ambiguous,
171        testCoverage,
172        problems,
173        limits: [
174          ...SOURCE_ANALYSIS_LIMITS,
175          'Default exclusions: tests/fixtures/benchmarks, reference/vendor copies, generated files, declarations and build output. Use --include-tests, --include-references or --include-generated for the corresponding source roles.',
176          'Diff is the selected Git commit versus current files, including untracked files; staged-only review and inferred rename/split identity are not claimed.',
177          'Coverage without matching source hashes is unavailable, never zero. Base CRAP is unavailable unless independently measured against that base.',
178          'Affected files are transitive importers in the covered source graph. Use fresh diff-impact/evidence for symbol consumers and runtime effects.',
179        ],
180      },
181    };
182  }
