184  function summarizeTestCoverage(
185    functions: readonly MeasuredFunction[],
186    requested: boolean,
187    inputProblem?: string,
188  ): SourceMaintenanceReport['coverage']['testCoverage'] {
189    let available = 0;
190    const reasons = new Set<string>();
191    for (const fn of functions) {
192      if (fn.coverage.status === 'available') available++;
193      else reasons.add(fn.coverage.reason);
194    }
195    if (requested && inputProblem) reasons.add(inputProblem);
196    return { requested, available, unavailable: functions.length - available, reasons: [...reasons] };
197  }
