199  function changedFunctions(before: readonly MeasuredFunction[], after: readonly MeasuredFunction[]): FunctionChange[] {
200    const key = (fn: MeasuredFunction): string => `${fn.file}:${fn.name}`;
201    const grouped = (functions: readonly MeasuredFunction[]): Map<string, MeasuredFunction[]> => {
202      const result = new Map<string, MeasuredFunction[]>();
203      for (const fn of functions) result.set(key(fn), [...(result.get(key(fn)) ?? []), fn]);
204      return result;
205    };
206    const old = grouped(before);
207    const next = grouped(after);
208    const changes: FunctionChange[] = [];
209    for (const name of [...new Set([...old.keys(), ...next.keys()])].sort()) {
210      const previous = old.get(name) ?? [];
211      const current = next.get(name) ?? [];
212      if (previous.length > 1 || current.length > 1) {
213        if (previous.map((fn) => fn.sourceHash).join() !== current.map((fn) => fn.sourceHash).join()) {
214          changes.push(
215            ...previous.map((fn) => ({ status: 'uncomparable' as const, before: fn })),
216            ...current.map((fn) => ({ status: 'uncomparable' as const, after: fn })),
217          );
218        }
219      } else if (previous[0] && current[0]) {
220        if (previous[0].sourceHash !== current[0].sourceHash)
221          changes.push({
222            status: 'modified',
223            before: previous[0],
224            after: current[0],
225            delta: {
226              cyclomatic: current[0].cyclomatic - previous[0].cyclomatic,
227              cognitive: current[0].cognitive - previous[0].cognitive,
228            },
229          });
230      } else if (current[0]) changes.push({ status: 'added', after: current[0] });
231      else if (previous[0]) changes.push({ status: 'removed', before: previous[0] });
232    }
233    return changes;
234  }
235  
236  function compareSourceFindings(
237    before: SourceAnalysis,
238    after: SourceAnalysis,
239    changed: Set<string>,
240    comparable: boolean,
241    dependenciesComparable = true,
242  ): SourceFinding[] {
243    const old = new Map(before.findings.map((finding) => [finding.id, finding]));
244    const next = new Map(after.findings.map((finding) => [finding.id, finding]));
245    const findings: SourceFinding[] = [];
246    const ambiguous = ambiguousFunctionNames(before.functions, after.functions);
247    const worsened = worsenedComplexityFunctions(before.functions, after.functions);
248    for (const finding of after.findings) {
249      if (finding.sites.length && !finding.sites.some((site) => changed.has(site.file))) continue;
250      const previous = old.get(finding.id);
251      let status: SourceFinding['status'] = 'existing';
252      if (
253        !comparable ||
254        finding.rule === 'crap' ||
255        finding.sites.some((site) => ambiguous.has(`${site.file}:${site.name}`))
256      )
257        status = 'uncomparable';
258      else if (!previous) status = 'introduced';
259      else if (finding.score > previous.score || worsened.has(finding.id)) status = 'worsened';
260      findings.push({ ...finding, status });
261    }
262    for (const finding of before.findings)
263      if (!next.has(finding.id) && finding.sites.some((site) => changed.has(site.file))) {
264        findings.push({
265          ...finding,
266          status:
267            comparable &&
268            (dependenciesComparable ||
269              !['architecture', 'dependency-cycle', 'broken-dependency', 'responsibility'].includes(finding.rule))
270              ? 'resolved'
271              : 'uncomparable',
272        });
273      }
274    return findings;
275  }
276  
277  /** Ranking uses the larger normalized metric; comparison must preserve changes to either metric. */
278  function worsenedComplexityFunctions(
279    before: readonly MeasuredFunction[],
280    after: readonly MeasuredFunction[],
281  ): Set<string> {
282    const previous = new Map(before.map((fn) => [`complexity:${fn.file}:${fn.name}`, fn]));
283    const worsened = new Set<string>();
284    for (const fn of after) {
285      const id = `complexity:${fn.file}:${fn.name}`;
286      const old = previous.get(id);
287      if (old && (fn.cyclomatic > old.cyclomatic || fn.cognitive > old.cognitive)) worsened.add(id);
288    }
289    return worsened;
290  }
291  
292  function ambiguousFunctionNames(before: readonly MeasuredFunction[], after: readonly MeasuredFunction[]): Set<string> {
293    const count = (functions: readonly MeasuredFunction[]): Map<string, number> => {
294      const counts = new Map<string, number>();
295      for (const fn of functions) {
296        const key = `${fn.file}:${fn.name}`;
297        counts.set(key, (counts.get(key) ?? 0) + 1);
298      }
299      return counts;
300    };
301    const old = count(before),
302      next = count(after);
303    return new Set([...old.keys(), ...next.keys()].filter((key) => (old.get(key) ?? 0) > 1 || (next.get(key) ?? 0) > 1));
304  }
305  
306  function removedDependencyFindings(
307    before: SourceAnalysis,
308    after: SourceAnalysis,
309    changed: Set<string>,
310    comparable: boolean,
311  ): SourceFinding[] {
312    const previous = new Map(before.imports.map((edge) => [`${edge.file}:${edge.specifier}`, edge]));
313    const findings: SourceFinding[] = [];
314    for (const edge of after.imports) {
315      if (edge.target) continue;
316      const old = previous.get(`${edge.file}:${edge.specifier}`);
317      if (!old?.target || !changed.has(old.target) || after.graph.has(old.target)) continue;
318      findings.push({
319        id: `broken-dependency:${edge.file}:${edge.specifier}`,
320        rule: 'broken-dependency',
321        evidence: 'derived',
322        status: comparable ? 'introduced' : 'uncomparable',
323        summary: 'An unchanged import still refers to a removed source file.',
324        sites: [
325          { file: edge.file, line: edge.line },
326          { file: old.target, line: 1 },
327        ],
328        score: 1,
329        details: [
330          `${edge.specifier} resolved to ${old.target} at the base commit and no longer resolves in current source.`,
331        ],
332      });
333    }
334    return findings;
335  }
336  
337  function affectedImporters(graph: ReadonlyMap<string, ReadonlySet<string>>, changed: Set<string>): string[] {
338    const incoming = new Map<string, Set<string>>();
339    for (const [file, targets] of graph)
340      for (const target of targets) {
341        const sources = incoming.get(target) ?? new Set<string>();
342        sources.add(file);
343        incoming.set(target, sources);
344      }
345    const seen = new Set(changed);
346    const queue = [...changed];
347    for (let cursor = 0; cursor < queue.length; cursor++)
348      for (const file of incoming.get(queue[cursor]!) ?? []) {
349        if (!seen.has(file)) {
350          seen.add(file);
351          queue.push(file);
352        }
353      }
354    return [...seen].filter((file) => !changed.has(file)).sort();
355  }

