 57  export const SOURCE_ANALYSIS_LIMITS = [
 58    `TS/JS implemented functions; metric rules ${FUNCTION_METRIC_RULES}. Cognitive counts structural nesting and logical sequences; recursion and interprocedural behavior are not measured.`,
 59    'Duplication compares whole function body tokens (at least 60 tokens), retaining literals and property names. Renamed local bindings are candidates; similarity does not prove interchangeable behavior or justify deletion.',
 60    'Dependencies cover static relative imports and re-exports, including type imports. Package aliases, CommonJS, dynamic imports, runtime handoffs, and other languages require indexed evidence or source inspection.',
