 64  export function analyzeSourceSnapshot(
 65    snapshot: SourceSnapshot,
 66    coverage: ReviewCoverage = { files: {}, problem: 'No source-matched coverage supplied.' },
 67    architecture?: ArchitectureConfig,
 68  ): SourceAnalysis {
 69    architecture ??= snapshot.project.architecture;
 70    const functions: MeasuredFunction[] = [];
 71    const imports: SourceImport[] = [];
 72    const bindingFacts: MaintenanceBindingFacts[] = [];
 73    const problems = [...snapshot.problems];
 74    for (const [file, source] of snapshot.files) {
 75      const analysis = analyzeSourceFunctions(file, source);
 76      problems.push(...analysis.errors);
 77      if (analysis.errors.length > 0) continue;
 78      functions.push(
 79        ...analysis.functions.map((fn) => ({
 80          ...fn,
 81          coverage: functionCoverage(fn, analysis.functions, source, coverage),
 82        })),
 83      );
 84      const fileImports = maintenanceImports(analysis.sourceFile, snapshot.files, snapshot.project, analysis.checker);
 85      for (const edge of fileImports) edge.role = sourceTestFile(file, architecture) ? 'test' : 'production';
 86      imports.push(...fileImports);
 87      if (!sourceTestFile(file, architecture)) bindingFacts.push(maintenanceBindings(analysis, fileImports));
 88    }
 89    const files = [...snapshot.files.keys()];
 90    const graph = importGraph(files, imports);
 91    const policy = sourceArchitecture(files, imports, architecture);
 92    const findings = [
 93      ...complexityFindings(functions),
 94      ...duplicateFindings(functions),
 95      ...dependencyCycleFindings(files, productionImports(imports, architecture)),
 96      ...policy.findings,
 97      ...unresolvedImportFindings(imports),
 98      ...responsibilityFindings(bindingFacts),
 99    ];
100    return { functions, findings: findings.sort(compareFindings), imports, graph, problems, architecture: policy.rules };
101  }
102  
103  function complexityFindings(functions: readonly MeasuredFunction[]): SourceFinding[] {
104    const findings: SourceFinding[] = [];
105    for (const fn of functions) {
106      const site = { file: fn.file, line: fn.startLine, name: fn.name };
107      if (fn.cyclomatic > 10 || fn.cognitive > 15)
108        findings.push({
109          id: `complexity:${fn.file}:${fn.name}`,
110          rule: 'complexity',
111          evidence: 'derived',
112          summary: `${fn.name}: cyclomatic ${fn.cyclomatic}, cognitive ${fn.cognitive}.`,
113          sites: [site],
114          score: Math.max(fn.cyclomatic / 10, fn.cognitive / 15),
115          details: [
116            'Review branching and nesting while preserving decisions, effects, and error handling.',
117            ...fn.contributions
118              .filter((part) => part.cognitive > 1)
119              .map((part) => `${fn.file}:${part.line}:${part.column} ${part.kind}: +${part.cognitive} cognitive`),
120          ],
121        });
122      if (fn.coverage.status === 'available' && fn.coverage.crap! >= 30)
123        findings.push({
124          id: `crap:${fn.file}:${fn.name}`,
125          rule: 'crap',
126          evidence: 'derived',
127          score: fn.coverage.crap!,
128          sites: [site],
129          summary: `${fn.name}: CRAP ${fn.coverage.crap}, measured line coverage ${Math.round(fn.coverage.fraction! * 100)}%.`,
130          details: [
131            'CRAP = cyclomatic² × (1 − measured coverage)³ + cyclomatic. Improve tests and simplify behavior where justified.',
132          ],
133        });
134    }
135    return findings;
136  }
137  
138  function duplicateFindings(functions: readonly MeasuredFunction[]): SourceFinding[] {
139    const groups = new Map<string, MeasuredFunction[]>();
140    for (const fn of functions) {
141      if (fn.tokenCount < 60) continue;
142      const key = fn.renamedBodyHash;
143      const group = groups.get(key) ?? [];
144      group.push(fn);
145      groups.set(key, group);
146    }
147    return [...groups.values()]
148      .filter((group) => group.length > 1)
149      .map((group) => {
150        const exact = new Set(group.map((fn) => fn.bodyHash)).size === 1;
151        const sites = group.map((fn) => ({ file: fn.file, line: fn.startLine, name: fn.name }));
152        return {
153          id: `duplication:${group[0]!.renamedBodyHash}`,
154          rule: 'duplication' as const,
155          evidence: 'candidate' as const,
156          summary: `${group.length} functions share ${exact ? 'identical body tokens' : 'body tokens after local binding renaming'}.`,
157          sites,
158          score: group.length,
159          details: [
160            `${group[0]!.tokenCount} tokens per body; comments and whitespace excluded; literals retained.`,
161            'Read both contracts and callers. If these implementations own the same rule, reuse one owner; otherwise retain the separate responsibilities.',
162          ],
163        };
164      });
165  }
166  
167  export function compareFindings(a: SourceFinding, b: SourceFinding): number {
168    const priority = {
169      'broken-dependency': 0,
170      architecture: 1,
171      'dependency-cycle': 2,
172      responsibility: 3,
173      duplication: 4,
174      crap: 5,
175      complexity: 6,
176    };
177    return priority[a.rule] - priority[b.rule] || b.score - a.score || a.id.localeCompare(b.id);
178  }
