  5  export interface MaintenanceFunctionBindings {
  6    fn: SourceFunction;
  7    declaration: number;
  8    exports: string[];
  9    /** Exact same-file declarations referenced by the function, including shared state and helpers. */
 10    bindings: number[];
 11    dependencies: string[];
 12  }
 13  
 14  export interface MaintenanceBindingFacts {
 15    functions: MaintenanceFunctionBindings[];
 16    consumers: { file: string; line: number; target: string; name: string }[];
 17  }
 18  
 19  /** A deliberately narrow provider: top-level functions and named ES imports, resolved by lexical binding identity. */
 20  export function maintenanceBindings(
 21    analysis: FunctionAnalysis,
 22    imports: readonly SourceImport[],
 23  ): MaintenanceBindingFacts {
 24    const { sourceFile: source, checker } = analysis;
 25    const nodes = topLevelFunctions(source);
 26    const importedBindings = new Map<ts.Symbol, string>();
 27    const consumers: MaintenanceBindingFacts['consumers'] = [];
 28    for (const statement of source.statements) {
 29      if (!ts.isImportDeclaration(statement) || !ts.isStringLiteralLike(statement.moduleSpecifier)) continue;
 30      const edge = imports.find(
 31        (item) => item.specifier === statement.moduleSpecifier.getText(source).slice(1, -1) && item.kind === 'value',
 32      );
 33      if (!edge || edge.role === 'test') continue;
 34      for (const binding of importBindings(statement)) {
 35        const symbol = checker.getSymbolAtLocation(binding.local);
 36        if (symbol) importedBindings.set(symbol, edge.target ?? `specifier:${edge.specifier}`);
 37        if (edge.target && edge.resolution === 'internal')
 38          consumers.push({ file: source.fileName, line: edge.line, target: edge.target, name: binding.imported });
 39      }
 40    }
 41    const exported = exportedBindings(source, checker);
 42    const functions = nodes.flatMap((node) => {
 43      const fn = analysis.functions.find((item) => item.startOffset === node.getStart(source));
 44      if (!fn) return [];
 45      const bindings = new Set<number>(),
 46        dependencies = new Set<string>();
 47      const visit = (child: ts.Node): void => {
 48        if (ts.isIdentifier(child)) {
 49          const symbol = checker.getSymbolAtLocation(child);
 50          const imported = symbol && importedBindings.get(symbol);
 51          if (imported) dependencies.add(imported);
 52          for (const declaration of symbol?.declarations ?? []) {
 53            if (declaration.getSourceFile() !== source || (declaration.pos >= node.pos && declaration.end <= node.end))
 54              continue;
 55            if (
 56              !ts.isImportSpecifier(declaration) &&
 57              !ts.isImportClause(declaration) &&
 58              !ts.isNamespaceImport(declaration)
 59            )
 60              bindings.add(declaration.getStart(source));
 61          }
 62        }
 63        ts.forEachChild(child, visit);
 64      };
 65      visit(node);
 66      const identity = functionIdentifier(node);
 67      const symbol = identity && checker.getSymbolAtLocation(identity);
 68      const declaration = (ts.isVariableDeclaration(node.parent) ? node.parent : node).getStart(source);
 69      return [
 70        {
 71          fn,
 72          declaration,
 73          exports: symbol ? (exported.get(symbol) ?? []) : [],
 74          bindings: [...bindings].sort((a, b) => a - b),
 75          dependencies: [...dependencies].sort(),
 76        },
 77      ];
 78    });
 79    return { functions, consumers };
 80  }
 81  
 82  function topLevelFunctions(source: ts.SourceFile): ts.FunctionLikeDeclaration[] {
 83    return source.statements.flatMap<ts.FunctionLikeDeclaration>((statement) => {
 84      if (ts.isFunctionDeclaration(statement) && statement.body) return [statement];
 85      if (!ts.isVariableStatement(statement)) return [];
 86      return statement.declarationList.declarations.flatMap((declaration) =>
 87        declaration.initializer &&
 88        (ts.isArrowFunction(declaration.initializer) || ts.isFunctionExpression(declaration.initializer))
 89          ? [declaration.initializer]
 90          : [],
 91      );
 92    });
 93  }
 94  
 95  function functionIdentifier(node: ts.FunctionLikeDeclaration): ts.Node | undefined {
 96    return ts.isVariableDeclaration(node.parent) ? node.parent.name : node.name;
 97  }
 98  
 99  function importBindings(node: ts.ImportDeclaration): { local: ts.Identifier; imported: string }[] {
100    const clause = node.importClause;
101    if (!clause || clause.isTypeOnly) return [];
102    const result = clause.name ? [{ local: clause.name, imported: 'default' }] : [];
103    const named = clause.namedBindings;
104    if (named && ts.isNamedImports(named))
105      for (const binding of named.elements)
106        if (!binding.isTypeOnly)
107          result.push({ local: binding.name, imported: (binding.propertyName ?? binding.name).text });
108    // Namespace imports join dependency groups conservatively; consumers cannot be attributed to one export.
109    if (named && ts.isNamespaceImport(named)) result.push({ local: named.name, imported: '*' });
110    return result;
111  }
112  
113  function exportedBindings(source: ts.SourceFile, checker: ts.TypeChecker): Map<ts.Symbol, string[]> {
114    const module = checker.getSymbolAtLocation(source);
115    const result = new Map<ts.Symbol, string[]>();
116    if (!module) return result;
117    for (const exported of checker.getExportsOfModule(module)) {
118      const local = exported.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(exported) : exported;
119      result.set(local, [...(result.get(local) ?? []), exported.name]);
120    }
121    return result;
122  }
