 33  export function maintenanceExclusion(file: string, opts: SourceScanOptions = {}): string | undefined {
 34    if (!/\.[cm]?[jt]sx?$/.test(file)) return 'unsupported-language';
 35    if (/\.d\.[cm]?ts$/.test(file)) return 'declaration';
 36    if (/(^|\/)(node_modules|dist|build|coverage|\.git|\.scipquery|\.next|\.nuxt|\.turbo|\.cache)(\/|$)/.test(file))
 37      return 'managed-output';
 38    if (!opts.includeGenerated && /(^|\/)(__generated__|generated)(\/|$)/.test(file)) return 'generated';
 39    if (
 40      !opts.includeReferences &&
 41      (/^(docs|agent_docs|\.agents|\.claude|\.codex)\//.test(file) ||
 42        /(^|\/)(vendor|third_party|third-party)(\/|$)/.test(file))
 43    )
 44      return 'reference';
 45    if (!opts.includeTests && (classifyFile(file) === 'test' || /(^|\/)(fixtures|benchmarks)(\/|$)/.test(file)))
 46      return 'test';
 47    return undefined;
 48  }
