 66  /** Read immutable blobs in one batch, including paths containing spaces or newlines. */
 67  export function baseSourceSnapshot(projectRoot: string, base: string, opts: SourceScanOptions = {}): SourceSnapshot {
 68    validateScanLimits(opts);
 69    const revision = gitRevision(projectRoot, base);
 70    const entries = git(projectRoot, ['ls-tree', '-r', '-z', revision]).toString('utf8').split('\0').filter(Boolean);
 71    const blobs = new Map<string, string>();
 72    for (const entry of entries) {
 73      const match = /^(100\d+) blob ([a-f0-9]+)\t([\s\S]+)$/.exec(entry);
 74      if (match) blobs.set(match[3]!, match[2]!);
 75    }
 76    const selected = [...blobs.keys()]
 77      .filter((file) => !maintenanceExclusion(file, opts))
 78      .sort()
 79      .slice(0, opts.maxFiles ?? SOURCE_SCAN_DEFAULTS.maxFiles);
 80    const contents = new Map<string, string>();
 81    let retainedBytes = 0;
 82    // Batches bound peak memory independently of the repository's total object size.
 83    for (let offset = 0; offset < selected.length; offset += 32) {
 84      const batch = selected.slice(offset, offset + 32);
 85      const sizes = git(
 86        projectRoot,
 87        ['cat-file', '--batch-check'],
 88        batch.map((file) => blobs.get(file)).join('\n') + '\n',
 89      )
 90        .toString('utf8')
 91        .trim()
 92        .split('\n');
 93      const readable = batch.filter(
 94        (_, index) => Number(sizes[index]?.split(' ')[2]) <= (opts.maxFileBytes ?? SOURCE_SCAN_DEFAULTS.maxFileBytes),
 95      );
 96      if (readable.length === 0) continue;
 97      const output = git(projectRoot, ['cat-file', '--batch'], readable.map((file) => blobs.get(file)).join('\n') + '\n');
 98      retainedBytes += output.length;
 99      if (retainedBytes > MAX_SNAPSHOT_BYTES) break;
100      let cursor = 0;
101      for (const file of readable) {
102        const headerEnd = output.indexOf(10, cursor);
103        const size = Number(output.subarray(cursor, headerEnd).toString('utf8').split(' ')[2]);
104        if (headerEnd < 0 || !Number.isSafeInteger(size) || size < 0 || headerEnd + 1 + size > output.length) {
105          throw new Error('Invalid Git blob response while reading review base');
106        }
107        contents.set(file, output.subarray(headerEnd + 1, headerEnd + 1 + size).toString('utf8'));
108        cursor = headerEnd + 1 + size + 1;
109      }
110    }
111    return collectSnapshot(revision, [...blobs.keys()], opts, (file) => {
112      const content = contents.get(file);
113      if (content !== undefined) return content;
114      const blob = blobs.get(file);
115      if (file.endsWith('.json') && blob) {
116        const size = Number(git(projectRoot, ['cat-file', '-s', blob]).toString('utf8').trim());
117        if (size > (opts.maxFileBytes ?? SOURCE_SCAN_DEFAULTS.maxFileBytes))
118          throw new Error('configuration exceeds file byte limit');
119        return git(projectRoot, ['cat-file', 'blob', blob]).toString('utf8');
120      }
121      throw new Error('omitted by the Git source snapshot file/total byte limits');
122    });
123  }
