125  export function assertSourceSnapshotCurrent(
126    projectRoot: string,
127    snapshot: SourceSnapshot,
128    opts: SourceScanOptions = {},
129  ): string[] {
130    const inventory = presentProjectFiles(projectRoot);
131    const paths = inventory.filter((file) => !maintenanceExclusion(file, opts)).sort();
132    const problems: string[] = [];
133    if (
134      paths.length !== snapshot.eligibleFiles ||
135      paths.slice(0, opts.maxFiles ?? SOURCE_SCAN_DEFAULTS.maxFiles).some((file) => !snapshot.files.has(file))
136    ) {
137      problems.push('Eligible source file set changed or was incomplete during analysis; rerun after edits settle.');
138    }
139    if (
140      configurationInventory(inventory).join('\n') !== configurationInventory([...snapshot.project.inventory]).join('\n')
141    )
142      problems.push('Project configuration file set changed during analysis; rerun after edits settle.');
143    for (const [file, content] of [...snapshot.files, ...snapshot.project.inputs]) {
144      try {
145        if (
146          readProjectFile(projectRoot, file, {
147            maxBytes: opts.maxFileBytes ?? SOURCE_SCAN_DEFAULTS.maxFileBytes,
148          }).toString('utf8') !== content
149        ) {
150          problems.push(`${file}: source changed during analysis; rerun after edits settle.`);
151        }
152      } catch {
153        problems.push(`${file}: source unavailable during final freshness check.`);
154      }
155    }
156    return problems;
157  }
158  
159  function collectSnapshot(
160    revision: string,
161    paths: string[],
162    opts: SourceScanOptions,
163    read: (file: string) => string,
164  ): SourceSnapshot {
165    const exclusions: Record<string, number> = {};
166    const eligible = paths
167      .filter((file) => {
168        const reason = maintenanceExclusion(file, opts);
169        if (reason) exclusions[reason] = (exclusions[reason] ?? 0) + 1;
170        return !reason;
171      })
172      .sort();
173    const files = new Map<string, string>();
174    const problems: string[] = [];
175    const selected = eligible.slice(0, opts.maxFiles ?? SOURCE_SCAN_DEFAULTS.maxFiles);
176    if (selected.length < eligible.length)
177      problems.push(
178        `${eligible.length - selected.length} eligible files omitted by max-files; increase --max-files to cover them.`,
179      );
180    let bytes = 0;
181    for (const file of selected) {
182      try {
183        const content = read(file);
184        bytes += Buffer.byteLength(content);
185        if (bytes > MAX_SNAPSHOT_BYTES) {
186          problems.push(
187            `Snapshot exceeds ${MAX_SNAPSHOT_BYTES} bytes; ${selected.length - files.size} remaining files omitted.`,
188          );
189          break;
190        }
191        files.set(file, content);
192      } catch (error) {
193        problems.push(`${file}: ${error instanceof Error ? error.message : String(error)}`);
194      }
195    }
196    const project = maintenanceProject(paths, eligible, (file) => {
197      const content = read(file);
198      bytes += Buffer.byteLength(content);
199      if (bytes > MAX_SNAPSHOT_BYTES) throw new Error('source and configuration snapshot exceeds total byte limit');
200      return content;
201    });
202  
203    return {
204      revision,
205      files,
206      fingerprint: sourceHash(
207        [...files, ...project.inputs]
208          .sort(([a], [b]) => a.localeCompare(b))
209          .map(([file, content]) => `${JSON.stringify(file)}:${sourceHash(content)}`)
210          .join('\n'),
211      ),
212      eligibleFiles: eligible.length,
213      excludedFiles: paths.length - eligible.length,
214      exclusions,
215      project,
216      problems,
217    };
