 14  export interface SourceImport {
 15    file: string;
 16    line: number;
 17    specifier: string;
 18    target?: string;
 19    kind: 'value' | 'type';
 20    role: 'production' | 'test';
 21    syntax: 'import' | 'reexport' | 'require' | 'dynamic-import' | 'type-import';
