 27  /** Syntactic imports with compiler resolution against the same captured source and configuration. */
 28  export function maintenanceImports(
 29    source: ts.SourceFile,
 30    files: ReadonlyMap<string, string>,
 31    project: MaintenanceProject,
 32    checker: ts.TypeChecker,
 33  ): SourceImport[] {
 34    const imports: SourceImport[] = [];
 35    const configs = maintenanceFileConfigs(project, source.fileName);
 36    const add = (literal: ts.Node | undefined, kind: SourceImport['kind'], syntax: SourceImport['syntax']): void => {
 37      if (!literal) return;
 38      const specifier = ts.isStringLiteralLike(literal) ? literal.text : literal.getText(source);
 39      const resolved = ts.isStringLiteralLike(literal)
 40        ? resolveSourceImport(project, files, source.fileName, specifier, configs)
 41        : { resolution: 'dynamic' as const };
 42      imports.push({
 43        file: source.fileName,
 44        line: source.getLineAndCharacterOfPosition(literal.getStart(source)).line + 1,
 45        specifier,
 46        kind,
 47        role: classifyFile(source.fileName) === 'test' ? 'test' : 'production',
 48        syntax,
 49        configs: configs.map((config) => config.file).filter(Boolean),
 50        ...resolved,
 51      });
 52    };
 53    const visit = (node: ts.Node): void => {
 54      if (ts.isImportDeclaration(node)) add(node.moduleSpecifier, importKind(node), 'import');
 55      else if (ts.isExportDeclaration(node)) add(node.moduleSpecifier, exportKind(node), 'reexport');
 56      else if (ts.isImportEqualsDeclaration(node) && ts.isExternalModuleReference(node.moduleReference))
 57        add(node.moduleReference.expression, node.isTypeOnly ? 'type' : 'value', 'require');
 58      else if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument))
 59        add(node.argument.literal, 'type', 'type-import');
 60      else if (ts.isCallExpression(node)) {
 61        if (node.expression.kind === ts.SyntaxKind.ImportKeyword) add(node.arguments[0], 'value', 'dynamic-import');
 62        else if (
 63          ts.isIdentifier(node.expression) &&
 64          node.expression.text === 'require' &&
 65          !checker.getSymbolAtLocation(node.expression)
 66        )
 67          add(node.arguments[0], 'value', 'require');
 68      }
 69      ts.forEachChild(node, visit);
 70    };
 71    visit(source);
 72    return imports;
 73  }
 74  
 75  function importKind(node: ts.ImportDeclaration): SourceImport['kind'] {
 76    const clause = node.importClause;
 77    if (clause?.isTypeOnly) return 'type';
 78    const named = clause?.namedBindings;
 79    return !clause?.name &&
 80      named &&
 81      ts.isNamedImports(named) &&
 82      named.elements.length > 0 &&
 83      named.elements.every((item) => item.isTypeOnly)
 84      ? 'type'
 85      : 'value';
 86  }
 87  
 88  function exportKind(node: ts.ExportDeclaration): SourceImport['kind'] {
 89    const clause = node.exportClause;
 90    return node.isTypeOnly ||
 91      (clause &&
 92        ts.isNamedExports(clause) &&
 93        clause.elements.length > 0 &&
 94        clause.elements.every((item) => item.isTypeOnly))
 95      ? 'type'
 96      : 'value';
 97  }
