 99  function resolveSourceImport(
100    project: MaintenanceProject,
101    files: ReadonlyMap<string, string>,
102    file: string,
103    specifier: string,
104    configs: ReturnType<typeof maintenanceFileConfigs>,
105  ): Pick<SourceImport, 'resolution' | 'target' | 'alternatives'> {
106    if (isBuiltin(specifier)) return { resolution: 'builtin' };
107    // Assets are inventory facts, not TypeScript modules. Preserve their target without inventing an executable edge.
108    if (specifier.startsWith('.')) {
109      const asset = path.posix.normalize(path.posix.join(path.posix.dirname(file), specifier));
110      if (project.inventory.has(asset) && !/\.[cm]?[jt]sx?$/.test(asset))
111        return { resolution: 'excluded', target: asset };
112    }
113    if (project.ambiguousPackages.has(packageName(specifier))) return { resolution: 'ambiguous', alternatives: [] };
114    const results = configs.map((config) => {
115      let cache = project.resolutionCaches.get(config.file);
116      if (!cache) {
117        cache = ts.createModuleResolutionCache('/', (name) => name, { allowJs: true, ...config.options });
118        project.resolutionCaches.set(config.file, cache);
119      }
120      return ts.resolveModuleName(specifier, '/' + file, { allowJs: true, ...config.options }, project.host, cache)
121        .resolvedModule?.resolvedFileName;
122    });
123    const targets = [
124      ...new Set(
125        results
126          .filter((target): target is string => target !== undefined)
127          .map((target) => path.posix.normalize(project.host.realpath?.(target) ?? target).replace(/^\//, '')),
128      ),
129    ];
130    if (targets.length > 1 || (targets.length === 1 && results.some((result) => !result)))
131      return { resolution: 'ambiguous', alternatives: targets };
132    const target = targets[0];
133    if (target) return { resolution: files.has(target) ? 'internal' : 'excluded', target };
134    return { resolution: isInternalSpecifier(project, file, specifier) ? 'missing' : 'external' };
135  }
