 31  /** Capture the configuration consulted by the compiler alongside the source revision it describes. */
 32  export function maintenanceProject(
 33    paths: readonly string[],
 34    sourceFiles: readonly string[],
 35    read: (file: string) => string | undefined,
 36  ): MaintenanceProject {
 37    const inventory = new Set(paths);
 38    const inputs = new Map<string, string>();
 39    const problems: string[] = [];
 40    const readInput = (file: string): string | undefined => {
 41      if (inputs.has(file)) return inputs.get(file);
 42      // Compiler configuration may only read captured JSON metadata, never arbitrary source or the live filesystem.
 43      if (!file.endsWith('.json') || !inventory.has(file)) return undefined;
 44      try {
 45        const content = read(file);
 46        if (content !== undefined) inputs.set(file, content);
 47        return content;
 48      } catch (error) {
 49        problems.push(`${file}: configuration unavailable: ${error instanceof Error ? error.message : String(error)}`);
 50        return undefined;
 51      }
 52    };
 53    const host = typeScriptSnapshotHost(ts, paths, readInput);
 54    const directories = sourceDirectories(sourceFiles);
 55    const configs = readProjectConfigs(inventory, directories, host, problems);
 56    const ambiguousPackages = new Set<string>();
 57    const packages = readRepositoryPackages(inventory, directories, readInput, problems, ambiguousPackages);
 58    for (const file of paths) if (file === 'package.json' || file.endsWith('/package.json')) readInput(file);
 59    if (inventory.has('.scipquery.json')) readInput('.scipquery.json');
 60    const capturedHost = typeScriptSnapshotHost(ts, paths, (file) => inputs.get(file));
 61    return {
 62      inputs,
 63      inventory,
 64      configs,
 65      packages,
 66      host: packageHost(capturedHost, packages),
 67      problems,
 68      architecture: snapshotArchitecture(inputs.get('.scipquery.json'), problems),
 69      resolutionCaches: new Map(),
 70      fileConfigs: new Map(),
 71      ambiguousPackages,
 72    };
 73  }
 74  
 75  function sourceDirectories(files: readonly string[]): Set<string> {
 76    const directories = new Set<string>(['.']);
 77    for (const file of files) {
 78      let directory = path.posix.dirname(file);
 79      while (!directories.has(directory)) {
 80        directories.add(directory);
 81        directory = path.posix.dirname(directory);
 82      }
 83    }
 84    return directories;
 85  }
 86  
 87  function readProjectConfigs(
 88    inventory: ReadonlySet<string>,
 89    directories: ReadonlySet<string>,
 90    host: ts.ParseConfigHost,
 91    problems: string[],
 92  ): MaintenanceProjectConfig[] {
 93    const queue = [...directories].flatMap((directory) => {
 94      const candidates = ['tsconfig.json', 'jsconfig.json'].map((name) => path.posix.join(directory, name));
 95      return candidates.filter((file) => inventory.has(file)).slice(0, 1);
 96    });
 97    const seen = new Set<string>();
 98    const configs: MaintenanceProjectConfig[] = [];
 99    for (let index = 0; index < queue.length; index++) {
100      const file = queue[index]!;
101      if (seen.has(file)) continue;
102      seen.add(file);
103      const absolute = '/' + file;
104      const content = ts.readConfigFile(absolute, host.readFile);
105      if (content.error) {
106        problems.push(`${file}: ${ts.flattenDiagnosticMessageText(content.error.messageText, ' ')}`);
107        continue;
108      }
109      const parsed = ts.parseJsonConfigFileContent(
110        content.config,
111        host,
112        path.posix.dirname(absolute),
113        undefined,
114        absolute,
115      );
116      for (const error of parsed.errors) {
117        // Empty solution projects and source-only snapshots need not contain executable input files.
118        if (error.code !== 18003 && error.code !== 18002)
119          problems.push(`${file}: ${ts.flattenDiagnosticMessageText(error.messageText, ' ')}`);
120      }
121      configs.push({
122        file,
123        directory: path.posix.dirname(absolute),
124        files: new Set(parsed.fileNames),
125        options: parsed.options,
126      });
127      for (const reference of parsed.projectReferences ?? []) {
128        const target = reference.path.endsWith('.json')
129          ? reference.path
130          : path.posix.join(reference.path, 'tsconfig.json');
131        queue.push(target.replace(/^\//, ''));
132      }
133    }
134    return configs;
135  }
136  
137  function readRepositoryPackages(
138    inventory: ReadonlySet<string>,
139    directories: ReadonlySet<string>,
140    read: (file: string) => string | undefined,
141    problems: string[],
142    ambiguous: Set<string>,
143  ): Map<string, string> {
144    const packages = new Map<string, string>();
145    for (const directory of directories) {
146      const file = path.posix.join(directory, 'package.json');
147      if (!inventory.has(file)) continue;
148      try {
149        const raw: unknown = JSON.parse(read(file) ?? '{}');
150        if (!isRecordObject(raw) || typeof raw.name !== 'string') continue;
151        if (ambiguous.has(raw.name)) continue;
152        const previous = packages.get(raw.name);
153        if (previous && previous !== directory) {
154          problems.push(`${file}: repository package name ${raw.name} is also declared in ${previous}.`);
155          ambiguous.add(raw.name);
156          packages.delete(raw.name);
157          continue;
158        }
159        packages.set(raw.name, directory);
160      } catch {
161        problems.push(`${file}: malformed package metadata.`);
162      }
163    }
164    return packages;
165  }
166  
167  function packageHost(host: ts.ModuleResolutionHost, packages: ReadonlyMap<string, string>): ts.ModuleResolutionHost {
168    const canonical = (file: string): string => {
169      const marker = '/node_modules/';
170      const offset = file.lastIndexOf(marker);
171      if (offset < 0) return file;
172      const specifier = file.slice(offset + marker.length);
173      const name = packageName(specifier);
174      const directory = packages.get(name);
175      return directory === undefined ? file : path.posix.join('/', directory, specifier.slice(name.length));
176    };
177    return {
178      ...host,
179      fileExists: (file) => host.fileExists(canonical(file)),
180      readFile: (file) => host.readFile(canonical(file)),
181      directoryExists: (file) => file.endsWith('/node_modules') || host.directoryExists?.(canonical(file)) === true,
182      realpath: canonical,
183    };
184  }
185  
186  export function packageName(specifier: string): string {
187    return specifier.startsWith('@') ? specifier.split('/').slice(0, 2).join('/') : specifier.split('/')[0]!;
188  }
189  
190  /** A file can belong to several compiler projects; retain every nearest applicable configuration. */
191  export function maintenanceFileConfigs(project: MaintenanceProject, file: string): MaintenanceProjectConfig[] {
192    const cached = project.fileConfigs.get(file);
193    if (cached) return cached;
194    const absolute = '/' + file;
195    const containing = project.configs.filter((config) => config.files.has(absolute));
196    const candidates = containing.length
197      ? containing
198      : project.configs.filter((config) => absolute.startsWith(config.directory.replace(/\/$/, '') + '/'));
199    const nearest = Math.max(...candidates.map((config) => config.directory.length));
200    const result = candidates.length
201      ? candidates.filter((config) => config.directory.length === nearest)
202      : [{ file: '', directory: '/', files: new Set<string>(), options: DEFAULT_OPTIONS }];
203    project.fileConfigs.set(file, result);
204    return result;
205  }
206  
207  export function isInternalSpecifier(project: MaintenanceProject, file: string, specifier: string): boolean {
208    if (specifier.startsWith('.') || specifier.startsWith('/') || specifier.startsWith('#')) return true;
209    if (project.packages.has(packageName(specifier))) return true;
210    return maintenanceFileConfigs(project, file).some((config) =>
211      Object.keys(config.options.paths ?? {}).some((pattern) => {
212        const [prefix, suffix] = pattern.split('*');
213        return suffix === undefined ? specifier === pattern : specifier.startsWith(prefix!) && specifier.endsWith(suffix);
214      }),
215    );
216  }
217  
218  function snapshotArchitecture(raw: string | undefined, problems: string[]): ArchitectureConfig | undefined {
219    if (raw === undefined) return undefined;
220    const decoded = decodeProjectConfig(raw);
221    if (decoded.kind === 'malformed' || decoded.kind === 'unsupported') {
222      problems.push(`.scipquery.json: ${decoded.kind === 'malformed' ? decoded.reason : 'unsupported schema version'}`);
223      return undefined;
224    }
225    const diagnostics: ArchitectureConfigDiagnostic[] = [];
226    validateArchitectureConfig(decoded.config, diagnostics);
227    if (diagnostics.some((item) => item.level === 'error')) {
228      problems.push(...diagnostics.map((item) => `.scipquery.json ${item.path}: ${item.message}`));
229      return undefined;
230    }
231    return decoded.config.architecture;
232  }

